using Microsoft.AspNetCore.Http.Json;
using Service;
using System.Text.Json;

WebApplicationBuilder builder = WebApplication.CreateBuilder(args);

builder.Services.ConfigureHttpJsonOptions(options =>
{
    options.SerializerOptions.PropertyNamingPolicy = JsonNamingPolicy.CamelCase;
});

string connectionString = builder.Configuration.GetConnectionString("Sqlite") ?? "Data Source=links.db";
string baseUrl = builder.Configuration["BaseUrl"] ?? "http://localhost:5000/";

SchemaInitializer.Initialize(connectionString);

builder.Services.AddSingleton(new LinkRepository(connectionString));
builder.Services.AddSingleton(sp => new LinkService(sp.GetRequiredService<LinkRepository>(), baseUrl));

WebApplication app = builder.Build();

app.MapGet("/health/live", () => Results.Ok(HealthStatus.Live));

app.MapPost("/api/v1/links", async (CreateLinkRequest request, LinkService service) =>
{
    CreateOutcome outcome = await service.CreateAsync(request);
    return outcome.Kind switch
    {
        CreateOutcomeKind.Invalid => Results.Json(new ErrorResponse("invalid_request", outcome.Error!), statusCode: StatusCodes.Status400BadRequest),
        CreateOutcomeKind.AliasTaken => Results.Json(new ErrorResponse("alias_taken", "The requested alias is already taken."), statusCode: StatusCodes.Status409Conflict),
        CreateOutcomeKind.Created => Results.Json(new CreateLinkResponse(outcome.Code!, outcome.ShortUrl!), statusCode: StatusCodes.Status201Created),
        _ => Results.Problem(),
    };
});

app.MapGet("/api/v1/links/{code}/stats", async (string code, LinkService service) =>
{
    LinkStats? stats = await service.GetStatsAsync(code);
    if (stats is null)
    {
        return Results.Json(new ErrorResponse("not_found", "No link exists for this code."), statusCode: StatusCodes.Status404NotFound);
    }

    return Results.Json(stats, statusCode: StatusCodes.Status200OK);
});

app.MapGet("/{code}", async (string code, LinkService service) =>
{
    RedirectResult result = await service.RedirectAsync(code);
    return result.Kind switch
    {
        RedirectKind.Redirect => Results.Redirect(result.Url!, permanent: false),
        RedirectKind.NotFound => Results.Json(new ErrorResponse("not_found", "No link exists for this code."), statusCode: StatusCodes.Status404NotFound),
        RedirectKind.Expired => Results.Json(new ErrorResponse("expired", "The link has expired."), statusCode: StatusCodes.Status410Gone),
        _ => Results.Problem(),
    };
});

app.Run();

/// <summary>What the liveness endpoint reports.</summary>
public sealed record HealthStatus(string Status)
{
    /// <summary>The service is up.</summary>
    public static HealthStatus Live { get; } = new("live");
}

--- README.md ---
# URL Shortener Service

A REST API service that creates short links, redirects to original URLs while tracking clicks, and reports per-link statistics. Backed by SQLite; single-process, no authentication.

## Quick Start

### Building

```bash
dotnet build
```

### Running

```bash
dotnet run
```

The service listens on `http://localhost:5000` by default. The SQLite database is created automatically at `links.db` on first run.

### Configuration

Configuration is read from `appsettings.json` or environment variables:

- `BaseUrl` (default: `http://localhost:5000/`): The scheme, host, and optional port used to construct absolute short URLs returned by the create endpoint. Must be a valid base URL ending in `/`.
- `ConnectionStrings:Sqlite` (default: `Data Source=links.db`): SQLite connection string.

Example override via environment:
```bash
BaseUrl=https://short.example.com/ dotnet run
```

## API Endpoints

### POST /api/v1/links

Create a short link from a long URL.

**Request body:**
```json
{
  "url": "https://example.com/some/long/path",
  "alias": "my-link",
  "expiresAt": "2026-12-31T23:59:59Z"
}
```

**Fields:**
- `url` (required, string): The target URL. Must be an absolute URL with scheme `http` or `https`. Host (if an IP literal) must not be loopback, link-local, or RFC 1918 private.
- `alias` (optional, string): A caller-supplied short code. Must match `^[A-Za-z0-9]{1,32}$`. If omitted, a code is generated automatically. Must be unique across all links.
- `expiresAt` (optional, string): ISO-8601 UTC timestamp when this link expires (inclusive). Must include explicit UTC designator (`Z` or `+00:00`). If omitted, the link never expires.

**Success response (201 Created):**
```json
{
  "code": "my-link",
  "shortUrl": "http://localhost:5000/my-link"
}
```

**Error responses:**
- `400 Bad Request`: `url` is missing, `url` scheme is not http/https, `url` host is loopback/link-local/RFC1918 IP, `alias` malformed, or `expiresAt` is not valid ISO-8601 UTC.
  ```json
  {
    "error": "invalid_request",
    "message": "url scheme must be http or https"
  }
  ```
- `409 Conflict`: The requested `alias` is already taken. No row is created.
  ```json
  {
    "error": "alias_taken",
    "message": "The requested alias is already taken."
  }
  ```

**Worked example:**

```bash
curl -X POST http://localhost:5000/api/v1/links \
  -H "Content-Type: application/json" \
  -d '{
    "url": "https://github.com/torvalds/linux",
    "alias": "linux"
  }'
```

Response:
```json
{
  "code": "linux",
  "shortUrl": "http://localhost:5000/linux"
}
```

Create a link with auto-generated code:

```bash
curl -X POST http://localhost:5000/api/v1/links \
  -H "Content-Type: application/json" \
  -d '{
    "url": "https://www.rust-lang.org"
  }'
```

Response:
```json
{
  "code": "1",
  "shortUrl": "http://localhost:5000/1"
}
```

### GET /{code}

Redirect to the original URL and increment the click count.

**Parameters:**
- `code` (path, string): The short code.

**Success response (302 Found):**
- Redirects to the original URL.
- `Location` header contains the original URL.
- Click count for this link is incremented by 1.

**Error responses:**
- `404 Not Found`: No link exists for this code.
  ```json
  {
    "error": "not_found",
    "message": "No link exists for this code."
  }
  ```
- `410 Gone`: The link exists but has expired. No redirect occurs; click count is not incremented.
  ```json
  {
    "error": "expired",
    "message": "The link has expired."
  }
  ```

**Worked example:**

```bash
curl -i http://localhost:5000/linux
```

Response:
```
HTTP/1.1 302 Found
Location: https://github.com/torvalds/linux
Date: Mon, 20 Jan 2025 10:30:00 GMT

```

### GET /api/v1/links/{code}/stats

Retrieve statistics for a short link.

**Parameters:**
- `code` (path, string): The short code.

**Success response (200 OK):**
```json
{
  "code": "linux",
  "url": "https://github.com/torvalds/linux",
  "createdAt": "2025-01-20T10:25:00Z",
  "expiresAt": null,
  "clickCount": 5
}
```

**Fields:**
- `code` (string): The short code.
- `url` (string): The original URL.
- `createdAt` (string, ISO-8601 UTC): When this link was created.
- `expiresAt` (string or null, ISO-8601 UTC): The expiry timestamp, or `null` if no expiry was set.
- `clickCount` (number): Total successful redirects via `GET /{code}`.

**Error response (404 Not Found):**
```json
{
  "error": "not_found",
  "message": "No link exists for this code."
}
```

**Worked example:**

```bash
curl http://localhost:5000/api/v1/links/linux/stats
```

Response:
```json
{
  "code": "linux",
  "url": "https://github.com/torvalds/linux",
  "createdAt": "2025-01-20T10:25:00Z",
  "expiresAt": null,
  "clickCount": 5
}
```

After following the short link again:

```bash
curl http://localhost:5000/api/v1/links/linux/stats
```

Response:
```json
{
